const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const location = ee.Geometry.Point([49.2917, -12.3494]); // Arrachart, Madagascar coordinates
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';
  const rainfallThresholdInches = 22;
  const rainfallThresholdMM = rainfallThresholdInches * 25.4; // Convert inches to mm

  // 2. Data Acquisition
  const rainfallCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(location);

  const collectionSize = rainfallCol.size().getInfo();
  console.log(`January 2020 rainfall images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate total monthly rainfall
  const totalRainfall = rainfallCol.sum();

  // Check for valid pixels
  const pixelCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: location,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get total rainfall
  const rainfallMM = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: location,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const rainfallInches = rainfallMM / 25.4;

  console.log(`Total rainfall: ${rainfallMM.toFixed(1)} mm (${rainfallInches.toFixed(1)} inches)`);
  console.log(`Threshold: ${rainfallThresholdMM.toFixed(1)} mm (${rainfallThresholdInches} inches)`);

  // 5. Validation & Final Answer
  if (rainfallMM === null || rainfallMM === undefined || isNaN(rainfallMM) || rainfallMM < 0) {
    console.log("<answer>C3</answer>");
  } else if (rainfallInches > rainfallThresholdInches) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
